final class RecordingLedger: Ledger {
    private var balances: [String: Int] = [:]
    private(set) var journal: [Operation] = []

    func deposit(_ id: String, amount: Int) {
        balances[id, default: 0] += amount               // working behaviour
        journal.append(.deposit(id: id, amount: amount)) // recorded interaction
    }
}
